const leadData = $('Get Pending Leads').item.json;
const aiText = ($input.first().json.text || '').trim();

// Prompt v4: never turn an unqualified lead or empty completion into an email.
if (/^NEEDS_REVIEW:/i.test(aiText)) return [{json:{needsReview:true,reviewReason:aiText.replace(/^NEEDS_REVIEW:\s*/i,''),recordId:leadData.id,businessName:leadData['Business Name']}}];
if (!/^SUBJECT:\s*\S+/i.test(aiText) || !/\n---\s*\n\s*\S/.test(aiText)) throw new Error('Email draft is empty or malformed; sending blocked.');


// ─── Parse AI output ───────────────────────────────────────────────────────
// Handles both "SUBJECT: ...\n---\n[body]" AND fallback with no separator
let subject = leadData['Business Name'] + ' + natural ingredients';
let emailBody = aiText;

if (aiText.includes('\n---\n')) {
  // Preferred format with proper separator
  const sepIndex = aiText.indexOf('\n---\n');
  const subjectPart = aiText.substring(0, sepIndex).trim();
  emailBody = aiText.substring(sepIndex + 5).trim();
  if (subjectPart.match(/^SUBJECT:/i)) {
    subject = subjectPart.replace(/^SUBJECT:\s*/i, '').trim();
  } else if (subjectPart.length > 0 && subjectPart.length < 120) {
    subject = subjectPart;
  }
} else if (aiText.includes('---')) {
  // Looser --- check (no surrounding newlines)
  const sepIndex = aiText.indexOf('---');
  const subjectPart = aiText.substring(0, sepIndex).trim();
  emailBody = aiText.substring(sepIndex + 3).trim();
  if (subjectPart.match(/^SUBJECT:/i)) {
    subject = subjectPart.replace(/^SUBJECT:\s*/i, '').trim();
  } else if (subjectPart.length > 0 && subjectPart.length < 120) {
    subject = subjectPart;
  }
} else {
  // Fallback: no --- at all — extract SUBJECT: line by scanning
  const lines = aiText.split('\n');
  const subIdx = lines.findIndex(l => l.match(/^SUBJECT:/i));
  if (subIdx !== -1) {
    subject = lines[subIdx].replace(/^SUBJECT:\s*/i, '').trim();
    emailBody = lines.slice(subIdx + 1).join('\n').trim();
  }
}

// ─── Clean: remove any SUBJECT: lines that leaked into the body ───────────
emailBody = emailBody.replace(/^SUBJECT:.*\n?/gim, '').trim();

// ─── Clean: remove em dashes (—) and en dashes (–) ───────────────────────
emailBody = emailBody.replace(/[\u2014\u2013]/g, ',').replace(/,\s*,/g, ',').trim();
subject = subject.replace(/[\u2014\u2013]/g, ' ').replace(/\s+/g, ' ').trim();

// ─── Clean: strip sign-off lines (Ayman, Example Brand, Example Brand) ──────────
emailBody = emailBody.split('\n').filter(function(line) {
  var low = line.toLowerCase().trim();
  if (low.match(/\bayman\b/)) return false;
    if (low === 'Example Brand' || low === 'Example Brand' || low === 'Example Brand' || low === 'Example Brand team' || low === 'team Example Brand' || low === 'Example Company') return false;
    if (low.indexOf('tel:') === 0 || low.indexOf('email:') === 0 || low.indexOf('web:') === 0 || low.indexOf('+212') !== -1 || low.indexOf('0661267490') !== -1 || low.indexOf('@Example Brand') !== -1 || low.indexOf('www.Example Brand') !== -1) return false;
    return true;
}).join('\n').trim();

// ─── Clean: strip common formal sign-offs ────────────────────────────────
emailBody = emailBody
  .replace(/\n*(Best regards|Kind regards|Warm regards|Regards|Sincerely|Cheers|Thanks|Thank you|Cordialement|Bien cordialement|Bien \u00e0 vous|Mit freundlichen Gr\u00fc\u00dfen|Atentamente|Saludos cordiales|Cordiali saluti|\u0645\u0639 \u0623\u0637\u064a\u0628 \u0627\u0644\u062a\u062d\u064a\u0627\u062a|\u062a\u062d\u064a\u0627\u062a\u064a|\u0645\u0639 \u062a\u062d\u064a\u0627\u062a\u064a|\u0634\u0643\u0631\u0627\u064b)[,.]?[\s\S]*$/im, '')
  .trim();

if (!subject.trim() || emailBody.trim().split(/\s+/).length < 15) throw new Error('Email draft is incomplete after cleanup; sending blocked.');

// ─── Build HTML ───────────────────────────────────────────────────────────
const paragraphs = emailBody.split('\n').map(function(l){ return l.trim(); }).filter(function(l){ return l !== ''; });

const isArabic = /[\u0600-\u06FF]/.test(emailBody);
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, function(c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}
function renderText(value) {
  if (!isArabic) return escapeHtml(value);
  // Isolate Latin names, brand names, acronyms, and numbers within Arabic text.
  return value.split(/([A-Za-z0-9][A-Za-z0-9 .@+\/_&-]*[A-Za-z0-9]|[A-Za-z0-9]+)/g)
    .map(function(part) {
      return /^[A-Za-z0-9]/.test(part)
        ? '<bdi dir="ltr">' + escapeHtml(part.trim()) + '</bdi>'
        : escapeHtml(part);
    }).join('');
}
const bodyHtml = paragraphs
  .map(function(p){ return '<p' + (isArabic ? ' dir="rtl" lang="ar"' : '') + ' style="margin:0 0 14px 0;font-size:15px;line-height:1.6;color:#1a1a1a;' + (isArabic ? 'direction:rtl;text-align:right;' : '') + '">' + renderText(p) + '</p>'; })
  .join('');

const signatureHtml = "<table style=\"margin-top:24px;font-size:13px;color:#666;line-height:1.5;border-top:1px solid #e0e0e0;padding-top:16px;\" cellpadding=\"0\" cellspacing=\"0\">\n  <tr><td style=\"font-weight:600;color:#2d5016;font-size:14px;\">Example Brand</td></tr>\n  <tr><td style=\"padding-top:4px;\">Tel: +212 6 61 26 74 90</td></tr>\n  <tr><td>Email: sales@example.com</td></tr>\n  <tr><td>Web: <a href=\"https://example.com\" style=\"color:#2d5016;text-decoration:none;\">example.com</a></td></tr>\n</table>";

const fullHtml = '<div' + (isArabic ? ' dir="rtl" lang="ar"' : '') + ' style="font-family:Arial,Helvetica,sans-serif;max-width:600px;' + (isArabic ? 'direction:rtl;text-align:right;' : '') + '">' + bodyHtml + '<div dir="ltr" style="direction:ltr;text-align:left;">' + signatureHtml + '</div></div>';

const plainText = paragraphs.join('\n\n') + '\n\n---\nExample Brand | +212 6 61 26 74 90 | sales@example.com';


return [{
  json: {
    to: leadData['Email'],
    subject: subject,
    body: fullHtml,
    plainBody: plainText,
    businessName: leadData['Business Name']
  }
}];
